const ROAM_UID_PATTERN = /^[A-Za-z0-9_-]{9}$/;

const isLegacyCanvasNodeRecord = (record: unknown): boolean => {
  if (
    typeof record !== "object" ||
    record === null ||
    Array.isArray(record)
  ) {
    return false;
  }

  const shape = record as Record<string, unknown>;
  if (shape.typeName !== "shape") return false;
  if (
    typeof shape.type !== "string" ||
    !ROAM_UID_PATTERN.test(shape.type)
  ) {
    return false;
  }

  if (
    typeof shape.props !== "object" ||
    shape.props === null ||
    Array.isArray(shape.props)
  ) {
    return false;
  }

  const props = shape.props as Record<string, unknown>;

  return (
    typeof props.uid === "string" &&
    ROAM_UID_PATTERN.test(props.uid) &&
    typeof props.w === "number" &&
    Number.isFinite(props.w) &&
    props.w > 0 &&
    typeof props.h === "number" &&
    Number.isFinite(props.h) &&
    props.h > 0
  );
};
